        const file=payload.get('logo');payload.delete('logo');
        if(file&&file.size){
          if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>5242880)throw {code:'INVALID_LOGO'};
          const bitmap=await createImageBitmap(file);const ratio=Math.min(1,1600/Math.max(bitmap.width,bitmap.height));
          const canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*ratio);canvas.height=Math.round(bitmap.height*ratio);if(canvas.width<100||canvas.height<100){bitmap.close();throw {code:'INVALID_LOGO'};}
          const ctx=canvas.getContext('2d');ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();
          const png=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!png||png.size>2097152)throw {code:'INVALID_LOGO'};payload.set('logo',png,'company-logo.png');
        }
