  Object.assign(actionCopy.zh,{"deleteInfo": "账户、资料、企业、需求、报价及上传文件将永久删除，无法撤销。请输入用户邮箱确认。", "removing": "正在删除账户和文件…", "actionError": "无法完成操作", "serverSetup": "自动删除文件需要配置服务器。请检查Vercel服务器环境变量。", "sqlSetup": "尚未执行用户删除SQL更新。", "retry": "删除尚未完成。开始后账户将被禁止登录。请再次点击删除用户以继续。", "forbidden": "需要管理员权限。不能删除自己或仍拥有管理员权限的账户。", "signin": "会话已过期，请重新登录。", "mismatch": "用户或邮箱已更改。请刷新列表后重试。"});
